import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); from figstyle import *
fig, ax = canvas(84)
# top: Z generated by 1
text(ax, 4, 78, 'un seul générateur : 1', 'resultat', 's', ha='left', weight='bold')
f = numberline(ax, 8, 78, 66, -3, 5, labels=False, role='fixe', arrow_right=False)
for v in range(-3, 6):
    disc(ax, f(v), 66, 1.0 if v not in (-3, 5) else 1.6, 'fixe' if v not in (-3, 5) else 'resultat')
text(ax, f(-3), 60, r'$-3\times 1$', 'resultat', 's')
text(ax, f(5), 60, r'$5\times 1$', 'resultat', 's')
disc(ax, f(1), 66, 1.6, 'sujet'); text(ax, f(1), 60, '1', 'sujet', 's')
arrow(ax, (f(0) + 1, 68.5), (f(5) - 1, 68.5), 'varie', lw=0.9, curve=-0.25)
# bottom: Z^2 with multiples of (2;1)
text(ax, 4, 49, 'couples : (2 ; 1) seul ne suffit pas', 'sujet', 's', ha='left', weight='bold')
s = 8.0; ox, oy = 12, 10
P = lambda x, y: (ox + x * s, oy + y * s)
line(ax, [P(-1, -0.5), P(5.3, 2.65)], 'sujet', lw=0.9, dash=True)
for x in range(-1, 6):
    for y in range(-1, 4):
        if (x, y) in [(-2, -1), (0, 0), (2, 1), (4, 2)]: continue
        disc(ax, *P(x, y), 0.8, 'fixe')
for (x, y) in [(0, 0), (2, 1), (4, 2)]:
    disc(ax, *P(x, y), 1.5, 'sujet')
arrow(ax, P(0, 0), P(2, 1), 'varie', lw=1.3)
disc(ax, *P(1, 0), 1.5, 'limite'); disc(ax, *P(0, 1), 1.5, 'limite')
text(ax, P(1, 0)[0] + 2, P(1, 0)[1] - 4, r'$(1\,;\,0)$', 'limite', 's', ha='left')
text(ax, P(0, 1)[0] - 2, P(0, 1)[1] + 4, r'$(0\,;\,1)$', 'limite', 's', ha='left')
text(ax, 70, 22, 'hors de la droite', 'limite', 's')
text(ax, 70, 17, 'jamais atteints', 'limite', 's')
save(fig, '57-159')
